  for (std::size_t i{0}, j{0}; (i < Lhs.count) && (j < Rhs.count);) {
    if (vector_index<Lhs>(i) < vector_index<Rhs>(j)) {
      ++i;
    } else if (vector_index<Rhs>(j) < vector_index<Lhs>(i)) {
      ++j;
    } else {
      result[index] = {.result = index, .lhs = i, .rhs = j};
      ++index;
      ++i;
      ++j;
    }
  }

  return result;
